<script setup>
const { me } = useMe();
const { data: mine, pending, error, refresh } = await useApiFetch('/api/me/player', { key: 'overview-player', default: () => ({ player: null }) });
const { data: codeData, error: codeError, refresh: refreshCodes } = await useApiFetch('/api/codes', { key: 'overview-codes', default: () => ({ codes: [] }) });
const { data: partyData, refresh: refreshParty } = await useApiFetch('/api/me/party', { key: 'overview-party', default: () => null });
const { data: ladder, error: ladderError, refresh: refreshLadder } = await useApiFetch('/api/leaderboard', { key: 'overview-ladder', query: { track: 'ranked', per: 20 }, default: () => null });
const player = computed(() => mine.value?.player);
const linked = computed(() => Boolean(player.value?.linked));
const codes = computed(() => (codeData.value?.codes || []).filter(c => c.active));
const rounds = computed(() => (player.value?.matches || []).slice(0, 5));
const leaders = computed(() => (ladder.value?.rows || []).slice(0, 5));
const match = computed(() => partyData.value?.match);
const party = computed(() => partyData.value?.party);
const queued = computed(() => Boolean(party.value?.queuedAt));
const date = value => new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' });
let poll;
onMounted(() => { poll = setInterval(() => { refresh(); refreshCodes(); refreshParty(); }, 15000); });
onBeforeUnmount(() => clearInterval(poll));
const anon = computed(() => !me.value.user);
const { data: live } = await useApiFetch('/api/stats', { key: 'overview-stats', default: () => null });
useSeo({ title: 'Ranked World - Competitive Gorilla Tag Ranked Codes and MMR', brandTitle: true, description: 'Ranked World is a competitive Gorilla Tag platform. Join ranked codes for your bracket, climb the MMR leaderboard and run scrims. Practice bots are coming soon.' });
</script>
<template>
<main id="main" class="wrap section world-overview"><section v-if="anon" class="home-hero"><div class="home-hero__copy"><h1>Ranked Gorilla Tag</h1><p class="home-lead">Four brackets, 15 divisions, one public ladder. Join a code for your bracket and every tag you land moves your MMR.</p><div class="home-cta"><NuxtLink class="btn btn--brand btn--large" to="/play">Connect Gorilla Tag</NuxtLink><NuxtLink class="btn btn--large" to="/ranked">How rating works</NuxtLink></div><p class="meta">Free to play. An independent community project, not affiliated with Another Axiom.</p></div><div class="home-hero__art" aria-hidden="true"><img src="/img/logo.png" alt="" width="600" height="685" /></div></section><div v-else class="world-page-title"><div><h1>Overview</h1></div><NuxtLink class="btn btn--brand" to="/play"><AppIcon name="play" />{{ linked ? 'Find a game' : 'Start playing' }}</NuxtLink></div><div v-if="error" role="alert" class="world-error"><p>We could not load your player information.</p><button class="btn" @click="refresh">Try again</button></div><div v-if="pending" class="world-skeleton" aria-label="Loading your progress" aria-busy="true" /><ProgressIdentity v-else-if="linked && player.ranked" :player="player" /><section v-else-if="!anon" class="world-intro"><div><h2>Connect Gorilla Tag</h2><NuxtLink class="btn btn--brand" to="/play">{{ me.user ? 'Connect your account' : 'Connect Gorilla Tag' }}</NuxtLink></div><div class="world-intro__art" aria-hidden="true"><img src="/img/badges/ruby_1.png" alt="" /><img src="/img/badges/sapphire.png" alt="" /></div></section><div v-if="!anon" class="world-columns"><section><div class="world-section-head"><h2>Ranked codes</h2><NuxtLink to="/play">All codes <AppIcon name="arrowRight" class="world-inline-arrow" /></NuxtLink></div><div v-if="codeError" class="world-empty" role="alert"><p>Codes are unavailable right now.</p><button class="btn" @click="refreshCodes">Try again</button></div><template v-else-if="codes.length"><div v-for="c in codes.slice(0, 3)" :key="c.code" class="world-code"><span class="world-code__icon"><AppIcon name="hash" /></span><div><strong>{{ c.code }}</strong><small>{{ c.category || codeData.bracket }} / {{ c.count || 0 }} players</small></div><RoomJoinButton :code="c.code" /></div></template><div v-else class="world-empty"><h3>{{ linked ? 'No codes open in your bracket' : 'Your bracket. Your competition.' }}</h3><p class="meta">{{ linked ? 'Codes open as players come online. Try a scrim while you wait.' : 'Connect your account to see the ranked codes available to you.' }}</p><NuxtLink class="btn" :to="'/play'">{{ linked ? 'See codes' : 'Connect your account' }}</NuxtLink></div></section><section class="world-session"><h3>{{ match ? (match.code || 'Preparing your room') : queued ? 'Finding your opponents' : 'Party' }}</h3><p class="meta">{{ match ? `${match.size} / ${match.state}` : queued ? 'Your party is in the queue. Open Scrims to check its status or cancel.' : party?.members?.length > 1 ? `${party.members.length} players in your party. Ready up and find a match.` : 'Invite players to your party to start a scrim.' }}</p><NuxtLink class="btn" to="/play?mode=scrims"><AppIcon name="users" />{{ match ? 'Open match' : queued ? 'View queue' : 'Open Scrims' }}</NuxtLink></section></div><section v-if="linked" class="world-rounds"><div class="world-section-head"><h2>Recent rounds</h2><NuxtLink to="/history">Match history <AppIcon name="arrowRight" class="world-inline-arrow" /></NuxtLink></div><template v-if="rounds.length"><div v-for="(m,i) in rounds" :key="m.roundId || i" class="world-result"><span class="world-result__position">{{ m.placement + 1 }}</span><div><strong>{{ m.code }}</strong><small>{{ m.afterElo - m.delta }} to {{ m.afterElo }} MMR</small></div><span class="world-result__date meta">{{ date(m.at || m.createdAt) }}</span><span class="world-result__delta" :class="m.delta >= 0 ? 'pos' : 'neg'">{{ m.delta >= 0 ? '+' : '' }}{{ m.delta }} MMR</span></div></template><div v-else class="world-empty"><h3>No matches yet</h3><NuxtLink to="/play" class="btn">Find a ranked code</NuxtLink></div></section><section v-else-if="!anon" class="world-rounds"><div class="world-section-head"><h2>The leaderboard</h2><NuxtLink to="/leaderboard">Leaderboard <AppIcon name="arrowRight" class="world-inline-arrow" /></NuxtLink></div><div v-if="ladderError" role="alert" class="world-empty"><p>We could not load the leaderboard.</p><button class="btn" @click="refreshLadder">Try again</button></div><template v-else-if="leaders.length"><NuxtLink v-for="p in leaders" :key="p.discordId" :to="`/player/${p.discordId}`" class="world-result"><span class="world-result__position">{{ p.rank }}</span><div><strong>{{ p.name }}</strong><small>{{ p.ranked.tier.name }}</small></div><span class="meta world-result__date">{{ p.ranked.rounds }} rounds</span><span class="world-result__delta">{{ num(p.ranked.elo) }} MMR</span></NuxtLink></template><div v-else class="world-empty"><h3>No ranked players yet</h3></div></section><template v-if="anon"><section class="home-live"><p v-if="live" class="home-facts"><span><strong>{{ num(live.live) }}</strong> ranked {{ live.live === 1 ? 'room' : 'rooms' }} open right now</span><span><strong>{{ num(live.rounds) }}</strong> rounds scored in the last 24 hours</span><span><strong>{{ num(live.players) }}</strong> players connected</span></p><div class="world-section-head"><h2>Top of the ladder right now</h2><NuxtLink to="/leaderboard">All {{ num(ladder?.total || 0) }} players</NuxtLink></div><div v-if="ladderError" role="alert" class="world-empty"><p>We could not load the leaderboard.</p><button class="btn" @click="refreshLadder">Try again</button></div><template v-else><NuxtLink v-for="p in leaders" :key="p.discordId" :to="`/player/${p.discordId}`" class="world-result"><span class="world-result__position">{{ p.rank }}</span><div><strong>{{ p.name }}</strong><small>{{ p.ranked.tier.name }}, {{ p.ranked.rounds }} rounds, {{ p.ranked.winRate }}% won</small></div><span class="meta world-result__date">{{ p.ranked.tier.category }} bracket</span><span class="world-result__delta">{{ num(p.ranked.elo) }} MMR</span></NuxtLink></template></section><AdSlot place="home" /><section class="home-rows"><h2>How you get in</h2><dl><div><dt>Connect</dt><dd>Sign in with Discord, then join a one time private code in Gorilla Tag. That ties your game account to your Discord, and it takes about a minute.</dd></div><div><dt>Get your codes</dt><dd>Ranked rooms are split into LOW, MID, HIGH and TOP. You see the codes for your bracket, plus the next one over when you are within 100 MMR of the line.</dd></div><div><dt>Play</dt><dd>Type the code at the computer in Gorilla Tag. A bot hosts the room, scores every tag and posts the result when the round ends. Quest and Steam both work.</dd></div></dl></section><section class="home-rows"><div class="world-section-head"><h2>How a round is scored</h2><NuxtLink to="/ranked">Full rating rules</NuxtLink></div><dl><div><dt>A tag</dt><dd>30 points, give or take 6 depending on the MMR of who you tagged.</dd></div><div><dt>Staying untagged</dt><dd>1 point for every second you survive.</dd></div><div><dt>When it ends</dt><dd>Players are ordered by points. Finish higher than your rating says you should and your MMR goes up. Rounds with fewer than 3 eligible players do not count.</dd></div></dl></section><section class="home-rows"><h2>What else is here</h2><dl><div><dt>Scrims</dt><dd>Make a party, queue as a team, and a bot referees the match. Scrims have their own rating, so a rough scrim never touches your ranked MMR. <NuxtLink to="/play?mode=scrims">Open scrims</NuxtLink></dd></div><div><dt>Anti-cheat</dt><dd>Every ranked room is watched by a bot that checks movement against the game's physics. It only flags. A staff member watches the clip and makes the call on every ban.</dd></div><div><dt>Replays</dt><dd>Scrims and practice matches are recorded, if you allow it, and play back in 3D with movement stats. <NuxtLink to="/replays">See replays</NuxtLink></dd></div><div><dt>Launcher</dt><dd>On Steam, the Windows launcher opens Gorilla Tag and joins your code for you. <NuxtLink to="/launcher">Download for Windows</NuxtLink></dd></div></dl></section><section class="home-why"><h2>Why it exists</h2><p>Most of a Gorilla Tag night disappears. You play well for two hours, the lobby resets, and none of it followed you anywhere. Ranked World keeps the record: your rounds are scored, your MMR moves, and the ladder says where you stand against everyone else who connected.</p><NuxtLink class="btn btn--brand" to="/play">Connect Gorilla Tag</NuxtLink></section></template></main>
</template>
